/*
  The Sabka Saathi logo, inlined as a base64 data URI for the Open Graph card.

  This is deliberately NOT read from public/logo.png with fs. Doing that put
  `public/logo.png` into Next's file trace for every route that renders the
  card, so `output: "standalone"` created a `.next/standalone/public/`
  containing that one file — and Firebase App Hosting's Next.js adapter skips
  copying any top-level directory that already exists in the output bundle:

      const existsInOutputBundle = await exists(join(outputBundleAppDir, path));
      if (!isbundleYamlDir && !existsInOutputBundle && !isApphostingYaml) {
        await copy(join(appDir, path), join(outputBundleAppDir, path));
      }
      // @apphosting/adapter-nextjs/dist/utils.js — copyResources()

  So the one traced file shadowed the real directory and all 116 other assets
  (every logo, service image and team photo) shipped missing and 404'd in
  production. A literal string cannot be traced, which is what makes this safe.

  Regenerate with scripts/geo/../ (one-off):
    sips -Z 320 public/logo.png --out /tmp/og-logo.png
    python3 -c "import base64;print(base64.b64encode(open('/tmp/og-logo.png','rb').read()).decode())"
*/

export const ogLogoDataUri =
  "data:image/png;base64,";
